def test_worked_example():
    p = solution.block_parameters(512, 8)
    assert p["attention"] == 1048576
    assert p["ffn"] == 2097152
    assert p["total"] == 3145728

def test_ffn_expands():
    assert solution.block_parameters(64, 4)["ffn"] == 2 * 4 * 64 * 64

def test_head_count_irrelevant():
    assert (solution.block_parameters(512, 16)["total"]
            == solution.block_parameters(512, 4)["total"])

def test_custom_expansion():
    p = solution.block_parameters(64, 4, 2)
    assert p["attention"] == 16384
    assert p["ffn"] == 16384
    assert p["total"] == 32768

def test_total_is_sum():
    p = solution.block_parameters(256, 8)
    assert p["total"] == p["attention"] + p["ffn"]

def test_indivisible_heads():
    try:
        solution.block_parameters(10, 3)
    except ValueError:
        return
    raise AssertionError("expected ValueError")

def test_bad_width():
    try:
        solution.block_parameters(0, 1)
    except ValueError:
        return
    raise AssertionError("expected ValueError")
